def recite(start, take=1):
    lines = []
    for count in range(start, start - take, -1):
        if lines:
            lines.append("")
        lines.extend(
            [
                f"{_bottles(count)},",
                f"{_bottles(count)},",
                "And if one green bottle should accidentally fall,",
                f"There'll be {_bottles(count - 1)}.",
            ]
        )
    return lines

def _bottles(count, capitalized=True):
    word = _NUMBERS[count]
    if not capitalized:
        word = word.lower()
    return f"{word} green bottle{'s' if count != 1 else ''} hanging on the wall"
